const fs = require('fs');
const buf = fs.readFileSync(0);
const len = buf.length;
let pos = 0;

function readInt() {
  while (pos < len && (buf[pos] < 48 || buf[pos] > 57) && buf[pos] !== 45) pos++;
  let sign = 1, x = 0;
  if (buf[pos] === 45) { sign = -1; pos++; }
  while (pos < len && buf[pos] >= 48 && buf[pos] <= 57) {
    x = x * 10 + (buf[pos] - 48);
    pos++;
  }
  return x * sign;
}

const N = readInt();
const adj = new Array(N + 1);
for (let i = 1; i <= N; i++) {
  const m = readInt();
  const a = new Array(m);
  for (let j = 0; j < m; j++) a[j] = readInt();
  adj[i] = a;
}

const color = new Int8Array(N + 1).fill(-1);
const queue = new Int32Array(N + 1);
let head = 0, tail = 0;
color[1] = 0;
queue[tail++] = 1;

while (head < tail) {
  const u = queue[head++];
  const cu = color[u];
  const nb = adj[u];
  for (let j = 0; j < nb.length; j++) {
    const v = nb[j];
    if (color[v] === -1) {
      color[v] = cu ^ 1;
      queue[tail++] = v;
    }
  }
}

const team1 = [];
const team2 = [];
for (let i = 1; i <= N; i++) {
  if (color[i] === 0) team1.push(i);
  else team2.push(i);
}

const cmp = (a, b) => a - b;
team1.sort(cmp);
team2.sort(cmp);

process.stdout.write(team1.join(' ') + '\n' + team2.join(' ') + '\n');
